(() => {
  const decodeContent = (value) =>
    JSON.parse(new TextDecoder().decode(Uint8Array.from(atob(value), (char) => char.charCodeAt(0))));

  const baseContent = decodeContent("");
  const expansionContent = decodeContent("");

  window.GAME_CONTENT = {
    ...baseContent,
    events: [...baseContent.events, ...expansionContent.events],
  };
})();
